```ts
// cpuData.ts
export interface CpuSample { t: number; v: number; }

const DAY_MS = 24 * 60 * 60 * 1000;
const SAMPLE_MS = 1000;
export const WINDOW_SIZE = DAY_MS / SAMPLE_MS; // 86400

// Deterministic-ish pseudo realistic generator
export function cpuBaseAt(t: number): number {
  const dayPhase = ((t % DAY_MS) / DAY_MS) * 2 * Math.PI;
  // busier during "working hours"
  return 32 + 14 * Math.sin(dayPhase - Math.PI / 3) + 6 * Math.sin(3 * dayPhase + 1);
}

export function createCpuFeed(now = Date.now()) {
  let prev = cpuBaseAt(now);
  const next = (t: number): number => {
    const base = cpuBaseAt(t);
    // mean reversion + noise + occasional spikes
    let v = prev + (base - prev) * 0.05 + (Math.random() - 0.5) * 6;
    if (Math.random() < 0.003) v += 25 + Math.random() * 30; // spike
    v = Math.max(1, Math.min(99, v));
    prev = v;
    return v;
  };
  return next;
}

export function generateInitialWindow(now: number, next) {
  const timeline: number[] = new Array(WINDOW_SIZE);
  const values: (number | null)[] = new Array(WINDOW_SIZE);
  const start = now - (WINDOW_SIZE - 1) * SAMPLE_MS;
  for (let i = 0; i < WINDOW_SIZE; i++) {
    timeline[i] = start + i * SAMPLE_MS;
    values[i] = Math.round(next(timeline[i]) * 10) / 10;
  }
  return {timeline, values};
}
```

Hmm, generating with random walk backward — the walk runs forward from `start`. Fine.

Actually, for spikes to decay, mean reversion at 0.05 handles it.

