import {useEffect, useRef} from 'react';
import Yagr from 'yagr';
import type {MinimalValidConfig, YagrTheme} from 'yagr';
import 'yagr/dist/index.css';
import './cpu-chart.css';
import {createCpuFeed, generateInitialWindow, SAMPLE_MS} from './cpuData';

const SERIES_COLOR: Record<YagrTheme, string> = {light: '#2a78d6', dark: '#3987e5'};
const SERIES_FILL: Record<YagrTheme, string> = {light: 'rgba(42, 120, 214, 0.14)', dark: 'rgba(57, 135, 229, 0.20)'};

function buildConfig(timeline, data, theme): MinimalValidConfig {...}

export function CpuLoadChart({theme, onStats}: {theme: YagrTheme; onStats?: (s: CpuStats) => void}) {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const chartRef = useRef<Yagr | null>(null);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const feed = createCpuFeed();
    const now = Date.now();
    const {timeline, values} = generateInitialWindow(now, feed);
    const chart = new Yagr(root, buildConfig(timeline, values, themeRef?…));
    chartRef.current = chart;

    const timer = window.setInterval(() => {
      const t = Date.now();
      const v = Math.round(feed(t) * 10) / 10;
      chart.setSeries([t], [{data: [v]}], {incremental: true, splice: true});
      onStatsRef.current?.(computeStats(chart));
    }, SAMPLE_MS);

    return () => {
      window.clearInterval(timer);
      chart.dispose();
      chartRef.current = null;
    };
  }, []);

  useEffect(() => {
    const chart = chartRef.current;
    if (!chart) return;
    chart.setTheme(theme);
    chart.setSeries('cpu', {color: SERIES_COLOR[theme], lineColor: SERIES_COLOR[theme]});
    chart.redraw(true, true);
  }, [theme]);

  return <div ref={rootRef} className="cpu-chart" />;
}
```

