```ts
/**
 * Simulated CPU telemetry: 24h sliding window at 1s resolution.
 * Kept framework-free so the chart component can own the feed imperatively.
 */

export const SAMPLE_MS = 1000;
export const WINDOW_MS = 24 * 60 * 60 * 1000;
export const WINDOW_SIZE = WINDOW_MS / SAMPLE_MS; // 86 400 points

export type CpuFeed = (t: number) => number;

/** Daily baseline: busier mid-day, quieter at night. */
function baseline(t: number): number {
  const phase = ((t % WINDOW_MS) / WINDOW_MS) * Math.PI * 2;
  return 34 + 16 * Math.sin(phase - Math.PI / 2.2) + 5 * Math.sin(3 * phase + 0.8);
}

/**
 * Mean-reverting random walk with occasional load spikes.
 * Returns a function producing the next sample for timestamp `t`.
 */
export function createCpuFeed(): CpuFeed {
  let prev = baseline(Date.now());
  return (t: number) => {
    let v = prev + (baseline(t) - prev) * 0.03 + (Math.random() - 0.5) * 5;
    if (Math.random() < 0.002) {
      v += 20 + Math.random() * 35; // deploy / batch-job style spike
    }
    v = Math.min(99, Math.max(1, v));
    prev = v;
    return Math.round(v * 10) / 10;
  };
}

export interface CpuWindow {
  timeline: number[];
  values: (number | null)[];
}

/** Backfills the last 24h so the chart opens with a full window. */
export function generateInitialWindow(feed: CpuFeed, now = Date.now()): CpuWindow {
  const timeline = new Array<number>(WINDOW_SIZE);
  const values = new Array<number>(WINDOW_SIZE);
  const start = now - (WINDOW_SIZE - 1) * SAMPLE_MS;
  for (let i = 0; i < WINDOW_SIZE; i++) {
    timeline[i] = start + i * SAMPLE_MS;
    values[i] = feed(timeline[i]);
  }
  return {timeline, values};
}

export interface CpuStats {
  current: number | null;
  avg: number | null;
  max: number | null;
}

export function computeStats(values: (number | null)[]): CpuStats {
  let sum = 0;
  let max = -Infinity;
  let n = 0;
  let current: number | null = null;
  for (let i = 0; i < values.length; i++) {
    const v = values[i];
    if (v == null) continue;
    sum += v; n++;
    if (v > max) max = v;
    if (i === values.length - 1) current = v;
  }
  ...
}
```

