import puppeteer from 'puppeteer';

const url = process.argv[2] || 'http://localhost:4173/';
const browser = await puppeteer.launch({headless: 'shell', args: ['--no-sandbox']});
const page = await browser.newPage();
await page.setViewport({width: 1280, height: 800});
page.on('console', (m) => {
  if (m.type() === 'error') console.log('PAGE ERROR:', m.text());
});
page.on('pageerror', (e) => console.log('PAGE EXCEPTION:', e.message));

await page.goto(url, {waitUntil: 'networkidle0'});
// let the realtime feed tick a few times
await new Promise((r) => setTimeout(r, 3500));
await page.screenshot({path: '/tmp/shot/light.png'});

// switch to dark theme
await page.click('.theme-toggle');
await new Promise((r) => setTimeout(r, 1200));
await page.screenshot({path: '/tmp/shot/dark.png'});

// sanity checks: chart exists, canvas painted, only ONE series after realtime ticks
const info = await page.evaluate(() => {
  const canvases = document.querySelectorAll('.cpu-chart canvas').length;
  const stats = [...document.querySelectorAll('.stat__value')].map((e) => e.textContent);
  const bodyClass = document.body.className;
  return {canvases, stats, bodyClass};
});
console.log(JSON.stringify(info, null, 2));
await browser.close();

