    rootClasses: chartRoot ? chartRoot.className : null,
    stats: [...document.querySelectorAll('.stat__value')].map((e) => e.textContent),
    bodyClass: document.body.className,
  };
});
console.log(JSON.stringify(info, null, 2));
await browser.close();

