42	        id: SERIES_ID,
43	        name: 'Загрузка CPU',
44	        type: 'area',
45	        scale: 'y',
46	        color: SERIES_FILL[theme],
47	        lineColor: SERIES_LINE[theme],
48	        lineWidth: 2,
49	        data,
50	      } as RawSerieData,
51	    ],
52	    chart: {
53	      appereance: {theme, locale: 'ru'},
54	      size: {
55	        // Stretch to the container and redraw (debounced) when it resizes.
56	        adaptive: true,
57	        resizeDebounceMs: 100,
58	      },
59	      // Drag on the plot zooms into the range, double-click resets.
60	      select: {zoom: true},
61	      series: {type: 'area', interpolation: 'linear'},
62	      timeMultiplier: 1, // timestamps are in milliseconds
63	    },
64	    scales: {
65	      y: {min: 0, max: 100},
66	    },
67	    axes: {
68	      y: {
69	        values: (_u, splits) => splits.map((s) => (s == null ? null : `${Math.round(s)}%`)),
70	      },
71	    },
72	    // Single series — the card title names the metric, no legend box needed.
73	    legend: {show: false},
74	    tooltip: {
75	      show: true,
76	      value: (v) => (v == null ? '—' : `${Number(v).toFixed(1)}%`),
77	    },
78	  };
79	}
