81	export interface CpuLoadChartProps {
82	  theme: YagrTheme;
83	  /** Called once per second with stats recomputed over the visible window. */
84	  onStats?: (stats: CpuStats) => void;
85	}
86	
87	/**
88	 * Interactive CPU-load chart.
89	 *
90	 * The chart instance is created once per mount and updated imperatively:
91	 * realtime ticks use incremental+splice setSeries (append the new sample,
92	 * drop the oldest — sliding 24h window) instead of recreating the chart.
93	 * React re-renders never touch the canvas.
94	 */
95	export function CpuLoadChart({theme, onStats}: CpuLoadChartProps) {
96	  const rootRef = useRef<HTMLDivElement | null>(null);
97	  const chartRef = useRef<Yagr | null>(null);
98	
99	  // Always point at the latest callback without re-running the mount effect.
100	  const onStatsRef = useRef(onStats);
101	  useEffect(() => {
102	    onStatsRef.current = onStats;
103	  }, [onStats]);
104	
105	  useEffect(() => {
106	    const root = rootRef.current;
107	    if (!root) return;
108	
109	    const feed = createCpuFeed();
110	    const {timeline, values} = generateInitialWindow(feed);
111	    const chart = new Yagr(root, buildConfig(timeline, values, theme));
112	    chartRef.current = chart;
113	
114	    const emitStats = () => {
115	      onStatsRef.current?.(computeStats(chart.config.series[0].data));
116	    };
117	    emitStats();
118	
119	    const timer = window.setInterval(() => {
120	      const t = Date.now();
121	      // NB: the payload must carry the series id — without it yagr would
122	      // add a brand-new series on every tick instead of appending points.
123	      chart.setSeries([t], [{id: SERIES_ID, data: [feed(t)]}], {incremental: true, splice: true});
124	      emitStats();
125	    }, SAMPLE_MS);
126	
127	    return () => {
128	      window.clearInterval(timer);
129	      // Releases the ResizeObserver, uPlot instance, DOM and listeners.
130	      chart.dispose();
131	      chartRef.current = null;
132	    };
133	    // The chart is created once per mount; theme changes are applied
134	    // through the effect below via setTheme/setSeries.
135	    // eslint-disable-next-line react-hooks/exhaustive-deps
136	  }, []);
137	
138	  useEffect(() => {
139	    const chart = chartRef.current;
140	    if (!chart) return;
141	    chart.setTheme(theme);
142	    chart.setSeries(SERIES_ID, {
143	      color: SERIES_FILL[theme],
144	      lineColor: SERIES_LINE[theme],
145	    } as Partial<RawSerieData>);
146	    chart.redraw(true, true);
147	  }, [theme]);
148	
149	  return <div ref={rootRef} className="cpu-chart" role="img" aria-label="График загрузки CPU за последние сутки" />;
150	}
